left:0!important;
top:0!important;
right:0!important;
height:2px!important;
background:linear-gradient(90deg,transparent,#d2ad62,transparent)!important;
opacity:.84!important;
}
.cw-story-head{
padding:22px 23px 18px!important;
border-bottom:1px solid rgba(207,171,96,.18)!important;
background:radial-gradient(circle at 15% 0,rgba(210,173,98,.13),transparent 46%),#151b24!important;
}
.cw-kicker{
display:inline-block!important;
margin:0 0 7px!important;
color:#d9b86e!important;
-webkit-text-fill-color:#d9b86e!important;
font-size:.78rem!important;
font-weight:700!important;
letter-spacing:.14em!important;
}
.cw-story-head h2{
margin:0!important;
color:#f4ead6!important;
-webkit-text-fill-color:#f4ead6!important;
font-size:1.52rem!important;
line-height:1.38!important;
