/* ===== §C 通用折叠面板 ===== */
.cw-panel{
position:relative!important;
display:block!important;
width:100%!important;
margin:14px 0!important;
border:1px solid var(--cw-line)!important;
border-radius:14px!important;
background:#111720!important;
box-shadow:0 12px 30px rgba(0,0,0,.25)!important;
overflow:hidden!important;
}
.cw-panel::before{
content:""!important;
position:absolute!important;
left:0!important;
top:0!important;
right:0!important;
height:2px!important;
background:linear-gradient(90deg,transparent,var(--cw-gold),transparent)!important;
opacity:.8!important;
}
.cw-panel>summary{
list-style:none!important;
cursor:pointer!important;
min-height:56px!important;
display:flex!important;
align-items:center!important;
gap:10px!important;
padding:13px 48px 13px 16px!important;
background:linear-gradient(90deg,rgba(210,173,98,.1),rgba(18,24,33,.96) 68%)!important;
color:#f0e6d2!important;
-webkit-text-fill-color:#f0e6d2!important;
font-weight:700!important;
position:relative!important;
user-select:none!important;
transition:background .18s ease,border-color .18s ease!important;
}
.cw-panel>summary::-webkit-details-marker{
display:none!important;
}
.cw-panel>summary::after{
content:"⌄"!important;
position:absolute!important;
right:17px!important;
top:50%!important;
transform:translateY(-50%) rotate(-90deg)!important;
color:var(--cw-gold)!important;
-webkit-text-fill-color:var(--cw-gold)!important;
font-size:20px!important;
line-height:1!important;
transition:transform .18s ease!important;
}
.cw-panel[open]>summary::after{
transform:translateY(-50%) rotate(0deg)!important;
}
.cw-panel>summary:hover{
background:linear-gradient(90deg,rgba(210,173,98,.14),#18202b 72%)!important;
}
.cw-panel[open]>summary{
border-bottom:1px solid rgba(207,171,96,.15)!important;
}
.cw-panel>summary:focus-visible{
outline:2px solid #d2ad62!important;
outline-offset:-3px!important;
}
.cw-panel>summary>span:not(.cw-summary-icon){
color:#f0e6d2!important;
-webkit-text-fill-color:#f0e6d2!important;
}
.cw-panel>summary small{
margin-left:auto!important;
color:#9c927f!important;
-webkit-text-fill-color:#9c927f!important;
font-size:.76rem!important;
font-weight:500!important;
letter-spacing:.045em!important;
white-space:nowrap!important;
}
.cw-summary-icon{
width:30px!important;
height:30px!important;
flex:0 0 30px!important;
display:inline-flex!important;
align-items:center!important;
justify-content:center!important;
border:1px solid var(--cw-line)!important;
border-radius:50%!important;
background:rgba(210,173,98,.09)!important;
color:var(--cw-gold)!important;
-webkit-text-fill-color:var(--cw-gold)!important;
font-size:14px!important;
box-shadow:inset 0 0 0 3px rgba(210,173,98,.035)!important;
transition:transform .18s ease,background .18s ease!important;
}
.cw-panel[open]>summary .cw-summary-icon{
transform:scale(1.04)!important;
background:rgba(210,173,98,.13)!important;
}
.cw-panel-body{
padding:16px!important;
background:#0f151d!important;
color:#e7decd!important;
-webkit-text-fill-color:#e7decd!important;
}
.cw-panel[open]>.cw-panel-body{
animation:cwPanelReveal .18s ease both!important;
}
@keyframes cwPanelReveal{
from{opacity:0;transform:translateY(-4px);}
to{opacity:1;transform:translateY(0);}
}

.cw-panel::details-content{
block-size:0!important;
opacity:0!important;
overflow:clip!important;
transition:block-size .18s ease,opacity .18s ease!important;
}
.cw-panel[open]::details-content{
block-size:auto!important;
opacity:1!important;
}


