#ai-send-button,
button[id*="send"]{
transition:none!important;
animation:none!important;
transform:none!important;
}
}


@media(max-width:680px){
.cw-npc-brief-grid{
grid-template-columns:1fr!important;
}
.cw-npc-brief-card{
padding:11px 12px!important;
box-shadow:none!important;
}
}

/* ===== §O 万里照影·超程铭刻 ===== */
.cw-runtime .cw-remote{border-color:rgba(92,166,178,.42)!important;background:linear-gradient(180deg,rgba(11,24,29,.97),rgba(7,12,17,.99))!important;box-shadow:0 12px 30px rgba(0,0,0,.3)!important;}
.cw-runtime .cw-remote>summary{background:linear-gradient(90deg,rgba(18,67,73,.52),rgba(25,30,38,.9),rgba(11,14,20,.98))!important;border-bottom-color:rgba(92,166,178,.22)!important;}
.cw-runtime .cw-remote .cw-summary-icon{border-color:rgba(113,207,215,.48)!important;background:rgba(68,146,155,.16)!important;color:#bceff0!important;-webkit-text-fill-color:#bceff0!important;}
.cw-runtime .cw-remote-roster{border-color:rgba(92,166,178,.27)!important;background:linear-gradient(180deg,rgba(11,25,30,.92),rgba(9,15,21,.96))!important;}
.cw-runtime .cw-remote-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:12px!important;}
.cw-runtime .cw-remote-card{border:1px solid rgba(92,166,178,.3)!important;border-radius:14px!important;background:linear-gradient(180deg,rgba(15,30,36,.96),rgba(9,15,21,.98))!important;padding:14px!important;color:#ddd5c7!important;-webkit-text-fill-color:#ddd5c7!important;box-shadow:inset 0 0 20px rgba(79,173,181,.025)!important;}
.cw-runtime .cw-remote-card>header{display:flex!important;justify-content:space-between!important;align-items:flex-start!important;gap:10px!important;padding-bottom:9px!important;margin-bottom:10px!important;border-bottom:1px dashed rgba(92,166,178,.24)!important;}
.cw-runtime .cw-remote-card>header h4{margin:0!important;color:#edf6ed!important;-webkit-text-fill-color:#edf6ed!important;font-size:1rem!important;}
.cw-runtime .cw-remote-card>header span{color:#91cdd1!important;-webkit-text-fill-color:#91cdd1!important;font-size:.78rem!important;text-align:right!important;}
.cw-runtime .cw-remote-card footer{margin-top:10px!important;padding-top:9px!important;border-top:1px dashed rgba(92,166,178,.2)!important;color:#91aeb0!important;-webkit-text-fill-color:#91aeb0!important;font-size:.76rem!important;line-height:1.65!important;}
@media(max-width:720px){.cw-runtime .cw-remote-grid{grid-template-columns:1fr!important;}.cw-runtime .cw-remote-card>header{display:block!important;}.cw-runtime .cw-remote-card>header span{display:block!important;text-align:left!important;margin-top:4px!important;}}

/* ===== §Q 天时经纬：夜潮体感与五幕追踪 ===== */
.cw-runtime .cw-longnight-section{
background:linear-gradient(145deg,rgba(27,21,39,.94),rgba(12,17,25,.97))!important;
border-color:rgba(167,126,203,.34)!important;
box-shadow:inset 3px 0 0 rgba(154,112,191,.56)!important;
}
.cw-runtime .cw-longnight-section>h3{
color:#e1c8f2!important;
-webkit-text-fill-color:#e1c8f2!important;
}
.cw-runtime .cw-longnight-grid{
display:grid!important;
grid-template-columns:repeat(2,minmax(0,1fr))!important;
gap:10px!important;
}
.cw-runtime .cw-longnight-grid>article{
display:flex!important;
flex-direction:column!important;
gap:6px!important;
min-width:0!important;
padding:12px 13px!important;
border:1px solid rgba(174,139,204,.22)!important;
border-radius:12px!important;
background:rgba(8,12,19,.58)!important;
}
.cw-runtime .cw-longnight-grid b{
color:#d7b7ef!important;
-webkit-text-fill-color:#d7b7ef!important;
font-size:.84em!important;
letter-spacing:.04em!important;
}
.cw-runtime .cw-longnight-grid span{
color:#d7d0dc!important;
-webkit-text-fill-color:#d7d0dc!important;
line-height:1.72!important;
}
.cw-runtime .cw-local-mainline .cw-row:nth-child(7){
background:rgba(175,120,74,.07)!important;
box-shadow:inset 3px 0 0 rgba(205,154,87,.42)!important;
}
@media(max-width:680px){
.cw-runtime .cw-longnight-grid{
grid-template-columns:1fr!important;
}
}
